-- Storehouse initial schema (PostgreSQL 13+)
--
-- Conventions:
--   * UUID primary keys are generated by clients so offline work can replay idempotently.
--   * Money is integer kobo (bigint); never floating point.
--   * Quantities are numeric(12,3) to support weighed goods.
--   * stock_movements is the only source of stock truth. Current stock is the stock_levels view.
--   * stock_movements and audit_events are append-only; corrections are reversing rows.
--
-- Run inside a transaction supplied by your migration tool (psql: BEGIN; \i 0001_init.sql; COMMIT;).

-- ---------------------------------------------------------------------------
-- Tenancy, people and policy
-- ---------------------------------------------------------------------------

create table stores (
  id                 uuid primary key,
  name               text not null,
  code               text not null unique,
  timezone           text not null default 'Africa/Lagos',
  currency           char(3) not null default 'NGN',
  address            text not null default '',
  trading_day_cutoff time not null default '00:00',
  settings           jsonb not null default '{}'::jsonb,
  created_at         timestamptz not null default now(),
  constraint stores_settings_object check (jsonb_typeof(settings) = 'object')
);

create table users (
  id                   uuid primary key,
  store_id             uuid not null references stores(id),
  name                 text not null,
  role                 text not null check (role in
                         ('owner','manager','purchasing','receiving','stock','cashier','auditor')),
  phone                text not null,
  active               boolean not null default true,
  password_hash        text,
  password_updated_at  timestamptz,
  must_change_password boolean not null default true,
  created_at           timestamptz not null default now(),
  deleted_at           timestamptz,
  constraint users_name_present check (length(btrim(name)) > 0)
);

create table locations (
  id              uuid primary key,
  store_id        uuid not null references stores(id),
  name            text not null,
  type            text not null check (type in
                    ('SELLING','STORAGE','QUARANTINE','DAMAGED','RETURNS')),
  selling_allowed boolean not null default false,
  active          boolean not null default true
);

-- ---------------------------------------------------------------------------
-- Catalogue and lots
-- ---------------------------------------------------------------------------

create table suppliers (
  id             uuid primary key,
  store_id       uuid not null references stores(id),
  name           text not null,
  contact_name   text not null default '',
  phone          text not null default '',
  email          text not null default '',
  lead_time_days int not null default 0 check (lead_time_days >= 0),
  payment_terms  text not null default '',
  min_order_kobo bigint not null default 0 check (min_order_kobo >= 0),
  active         boolean not null default true
);

create table products (
  id                  uuid primary key,
  store_id            uuid not null references stores(id),
  sku                 text not null,
  name                text not null,
  brand               text not null default '',
  category            text not null default '',
  barcode             text,
  base_unit           text not null default 'each' check (base_unit in
                        ('each','kg','litre','metre')),
  pack_size           numeric(12,3) not null default 1 check (pack_size > 0),
  pack_label          text not null default '',
  cost_kobo           bigint not null default 0 check (cost_kobo >= 0),
  price_kobo          bigint not null default 0 check (price_kobo >= 0),
  active              boolean not null default true,
  batch_tracked       boolean not null default true,
  perishable          boolean not null default false,
  expiry_warning_days int not null default 0 check (expiry_warning_days >= 0),
  reorder_point       numeric(12,3) not null default 0 check (reorder_point >= 0),
  safety_stock        numeric(12,3) not null default 0 check (safety_stock >= 0),
  reorder_multiple    numeric(12,3) not null default 1 check (reorder_multiple > 0),
  supplier_id         uuid references suppliers(id),
  default_location_id uuid references locations(id),
  unique (store_id, sku)
);

create table batches (
  id          uuid primary key,
  product_id  uuid not null references products(id),
  batch_no    text not null,
  expiry      date,
  received_at timestamptz not null,
  supplier_id uuid references suppliers(id),
  constraint batches_batch_no_present check (length(btrim(batch_no)) > 0)
);

-- ---------------------------------------------------------------------------
-- Stock ledger
-- ---------------------------------------------------------------------------

create table stock_movements (
  id               uuid primary key,
  store_id         uuid not null references stores(id),
  seq              bigint generated always as identity,
  type             text not null check (type in
                     ('OPENING','RECEIPT','SALE','VOID','RETURN','TRANSFER',
                      'ADJUSTMENT','WRITE_OFF','STATUS_CHANGE','COUNT')),
  product_id       uuid not null references products(id),
  batch_id         uuid not null references batches(id),
  qty              numeric(12,3) not null check (qty > 0),
  from_location_id uuid references locations(id),
  from_status      text,
  to_location_id   uuid references locations(id),
  to_status        text,
  unit_cost_kobo   bigint not null default 0 check (unit_cost_kobo >= 0),
  ref_type         text not null check (ref_type in
                     ('SALE','RECEIPT','TRANSFER','COUNT','WRITE_OFF',
                      'ADJUSTMENT','OPENING','SYSTEM')),
  ref_id           uuid,
  actor_id         uuid not null references users(id),
  reason           text,
  note             text,
  occurred_at      timestamptz not null,
  recorded_at      timestamptz not null default now(),
  device_id        text not null,
  constraint stock_movements_has_endpoint check (from_location_id is not null or to_location_id is not null),
  constraint stock_movements_from_status_valid check
    (from_status is null or from_status in
      ('SELLABLE','QUARANTINE','DAMAGED','EXPIRED','RECALL','RETURN_PENDING')),
  constraint stock_movements_to_status_valid check
    (to_status is null or to_status in
      ('SELLABLE','QUARANTINE','DAMAGED','EXPIRED','RECALL','RETURN_PENDING')),
  constraint stock_movements_from_complete check (from_location_id is null or from_status is not null),
  constraint stock_movements_to_complete check (to_location_id is null or to_status is not null),
  constraint stock_movements_from_status_scoped check (from_location_id is not null or from_status is null),
  constraint stock_movements_to_status_scoped check (to_location_id is not null or to_status is null)
);

-- ---------------------------------------------------------------------------
-- Sales
-- ---------------------------------------------------------------------------

create table sales (
  id            uuid primary key,
  store_id      uuid not null references stores(id),
  number        text not null,
  subtotal_kobo bigint not null check (subtotal_kobo >= 0),
  discount_kobo bigint not null default 0 check (discount_kobo >= 0),
  total_kobo    bigint not null check (total_kobo >= 0),
  payment       text not null check (payment in ('CASH','TRANSFER','CREDIT')),
  status        text not null default 'COMPLETED' check (status in
                  ('COMPLETED','VOIDED','PARTIAL_RETURN','RETURNED')),
  customer_name text,
  device_id     text not null,
  cashier_id    uuid not null references users(id),
  occurred_at   timestamptz not null,
  created_at    timestamptz not null default now(),
  voided_at     timestamptz,
  voided_by     uuid references users(id),
  void_reason   text,
  unique (store_id, number),
  constraint sales_discount_within_subtotal check (discount_kobo <= subtotal_kobo)
);

create table sale_lines (
  id              uuid primary key,
  sale_id         uuid not null references sales(id) on delete cascade,
  product_id      uuid not null references products(id),
  batch_id        uuid references batches(id),
  qty             numeric(12,3) not null check (qty > 0),
  unit_price_kobo bigint not null check (unit_price_kobo >= 0),
  unit_cost_kobo  bigint not null check (unit_cost_kobo >= 0),
  returned_qty    numeric(12,3) not null default 0,
  constraint sale_lines_returned_within_qty check (returned_qty >= 0 and returned_qty <= qty)
);

-- ---------------------------------------------------------------------------
-- Purchasing and receiving
-- ---------------------------------------------------------------------------

create table purchase_orders (
  id                           uuid primary key,
  store_id                     uuid not null references stores(id),
  number                       text not null,
  supplier_id                  uuid not null references suppliers(id),
  status                       text not null default 'DRAFT' check (status in
                                 ('DRAFT','PENDING_APPROVAL','APPROVED','SENT',
                                  'PART_RECEIVED','RECEIVED','CLOSED','CANCELLED')),
  expected_date                date,
  notes                        text not null default '',
  version                      int not null default 1 check (version > 0),
  created_by                   uuid not null references users(id),
  created_at                   timestamptz not null default now(),
  submitted_at                 timestamptz,
  approved_by                  uuid references users(id),
  approved_at                  timestamptz,
  approval_limit_snapshot_kobo bigint check
                                 (approval_limit_snapshot_kobo is null or approval_limit_snapshot_kobo >= 0),
  sent_at                      timestamptz,
  closed_at                    timestamptz,
  close_reason                 text,
  unique (store_id, number)
);

create table po_lines (
  id             uuid primary key,
  po_id          uuid not null references purchase_orders(id) on delete cascade,
  product_id     uuid not null references products(id),
  qty            numeric(12,3) not null check (qty > 0),
  received_qty   numeric(12,3) not null default 0 check (received_qty >= 0),
  unit_cost_kobo bigint not null check (unit_cost_kobo >= 0)
);

create table goods_receipts (
  id            uuid primary key,
  store_id      uuid not null references stores(id),
  number        text not null,
  supplier_id   uuid not null references suppliers(id),
  po_id         uuid references purchase_orders(id),
  status        text not null default 'DRAFT'
                  check (status in ('DRAFT','CONFIRMED','REVERSED')),
  delivery_note text not null default '',
  note          text not null default '',
  created_by    uuid not null references users(id),
  created_at    timestamptz not null default now(),
  confirmed_by  uuid references users(id),
  confirmed_at  timestamptz,
  unique (store_id, number)
);

create table receipt_lines (
  id             uuid primary key,
  receipt_id     uuid not null references goods_receipts(id) on delete cascade,
  product_id     uuid not null references products(id),
  expected_qty   numeric(12,3) not null check (expected_qty >= 0),
  accepted_qty   numeric(12,3) not null default 0 check (accepted_qty >= 0),
  damaged_qty    numeric(12,3) not null default 0 check (damaged_qty >= 0),
  rejected_qty   numeric(12,3) not null default 0 check (rejected_qty >= 0),
  short_qty      numeric(12,3) not null default 0 check (short_qty >= 0),
  unit_cost_kobo bigint not null check (unit_cost_kobo >= 0),
  batch_no       text not null,
  expiry         date,
  constraint receipt_lines_batch_no_present check (length(btrim(batch_no)) > 0)
);

-- ---------------------------------------------------------------------------
-- Counts and write-offs
-- ---------------------------------------------------------------------------

create table stock_counts (
  id                uuid primary key,
  store_id          uuid not null references stores(id),
  number            text not null,
  scope             text not null default '',
  location_id       uuid not null references locations(id),
  status            text not null default 'OPEN' check (status in
                      ('OPEN','SUBMITTED','RECOUNT_REQUIRED','PENDING_APPROVAL',
                       'POSTED','CANCELLED')),
  snapshot_seq      bigint not null check (snapshot_seq >= 0),
  counter_id        uuid not null references users(id),
  created_at        timestamptz not null default now(),
  submitted_by      uuid references users(id),
  submitted_at      timestamptz,
  approved_by       uuid references users(id),
  approved_at       timestamptz,
  rejection_comment text,
  posted_at         timestamptz,
  unique (store_id, number)
);

create table count_entries (
  id          uuid primary key,
  count_id    uuid not null references stock_counts(id) on delete cascade,
  product_id  uuid not null references products(id),
  system_qty  numeric(12,3) not null,
  counted_qty numeric(12,3) check (counted_qty is null or counted_qty >= 0),
  recount_qty numeric(12,3) check (recount_qty is null or recount_qty >= 0),
  note        text not null default ''
);

create table write_offs (
  id             uuid primary key,
  store_id       uuid not null references stores(id),
  number         text not null,
  product_id     uuid not null references products(id),
  batch_id       uuid not null references batches(id),
  qty            numeric(12,3) not null check (qty > 0),
  reason         text not null,
  note           text not null default '',
  unit_cost_kobo bigint not null check (unit_cost_kobo >= 0),
  value_kobo     bigint not null check (value_kobo >= 0),
  status         text not null default 'PENDING_APPROVAL'
                   check (status in ('PENDING_APPROVAL','POSTED','REJECTED')),
  requested_by   uuid not null references users(id),
  requested_at   timestamptz not null,
  decided_by     uuid references users(id),
  decided_at     timestamptz,
  decision_note  text,
  unique (store_id, number)
);

-- ---------------------------------------------------------------------------
-- Audit and sync support
-- ---------------------------------------------------------------------------

create table audit_events (
  id          uuid primary key,
  store_id    uuid not null references stores(id),
  seq         bigint generated always as identity,
  created_at  timestamptz not null default now(),
  actor_id    uuid not null references users(id),
  actor_name  text not null,
  action      text not null,
  entity_type text not null,
  entity_id   text not null,
  summary     text not null,
  before_data jsonb,
  after_data  jsonb,
  reason      text,
  prev_hash   text not null,
  hash        text not null,
  unique (store_id, seq)
);

create table sync_mutations (
  mutation_id uuid primary key,
  store_id    uuid not null references stores(id),
  device_id   text not null,
  applied_at  timestamptz not null default now()
);

create table alert_states (
  store_id      uuid not null references stores(id),
  alert_key     text not null,
  state         text not null default 'OPEN'
                  check (state in ('OPEN','ACKNOWLEDGED','SNOOZED','RESOLVED')),
  owner_role    text check (owner_role is null or owner_role in
                  ('owner','manager','purchasing','receiving','stock','cashier','auditor')),
  snoozed_until timestamptz,
  updated_by    uuid references users(id),
  updated_at    timestamptz not null default now(),
  primary key (store_id, alert_key)
);

-- ---------------------------------------------------------------------------
-- Append-only enforcement
-- ---------------------------------------------------------------------------

create function reject_mutation() returns trigger
language plpgsql
as $$
begin
  raise exception 'Table % is append-only', tg_table_name
    using errcode = 'restrict_violation';
end;
$$;

create trigger stock_movements_append_only
  before update or delete on stock_movements
  for each row execute function reject_mutation();

create trigger stock_movements_no_truncate
  before truncate on stock_movements
  for each statement execute function reject_mutation();

create trigger audit_events_append_only
  before update or delete on audit_events
  for each row execute function reject_mutation();

create trigger audit_events_no_truncate
  before truncate on audit_events
  for each statement execute function reject_mutation();

-- ---------------------------------------------------------------------------
-- Current stock projection
-- ---------------------------------------------------------------------------

create view stock_levels as
select store_id, product_id, batch_id, location_id, status, sum(qty) as qty
from (
  select store_id, product_id, batch_id,
         to_location_id as location_id, to_status as status, qty
  from stock_movements
  where to_location_id is not null
  union all
  select store_id, product_id, batch_id,
         from_location_id as location_id, from_status as status, -qty
  from stock_movements
  where from_location_id is not null
) legs
group by store_id, product_id, batch_id, location_id, status;

-- ---------------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------------

create unique index products_barcode_key
  on products (store_id, barcode)
  where barcode is not null and btrim(barcode) <> '';

create index batches_fefo_idx
  on batches (product_id, expiry, received_at);

create index stock_movements_product_idx
  on stock_movements (product_id, batch_id, occurred_at desc);

create index stock_movements_store_idx
  on stock_movements (store_id, seq);

create index stock_movements_ref_idx
  on stock_movements (ref_type, ref_id);

create index sales_store_idx on sales (store_id, occurred_at desc);
create index sale_lines_sale_idx on sale_lines (sale_id);

create index purchase_orders_store_idx on purchase_orders (store_id, status);
create index po_lines_po_idx on po_lines (po_id);

create index goods_receipts_store_idx on goods_receipts (store_id, created_at desc);
create index receipt_lines_receipt_idx on receipt_lines (receipt_id);

create index stock_counts_store_idx on stock_counts (store_id, status);
create index count_entries_count_idx on count_entries (count_id);

create index write_offs_store_idx on write_offs (store_id, status);

create index audit_events_entity_idx on audit_events (entity_type, entity_id);

create index users_store_idx on users (store_id) where deleted_at is null;

-- ---------------------------------------------------------------------------
-- Documentation
-- ---------------------------------------------------------------------------

comment on column stock_movements.qty is
  'Positive quantity. Direction is implied by the from/to endpoints; null endpoints are external.';
comment on table audit_events is
  'Append-only. seq is assigned by the database; hash chains over the previous event in the same store.';
comment on table users is
  'Deactivate or soft-delete users; documents and audit rows keep referencing the original row.';
comment on view stock_levels is
  'Current quantity per product, batch, location and status, derived from the ledger.';
